#!/bin/tcsh
#---------------------------------------------------------------
# Qflow technology variables for the project cell library pl018
# (TSMC 0.18 um models, SCMOS SCN6M_SUBM rules of the OSU018 kit,
# 0.8 x 8.0 um site; cells generated by step5_library/gen_library.py)
#---------------------------------------------------------------

set leffile=pl018_cells.lef
set spicefile=pl018_cells.sp
set libertyfile=pl018_cells.lib
set techleffile=""

# no sequential cells in this library (the ALU is combinational)

set bufcell=pl_buf	;# output buffer
set bufpin_in=A
set bufpin_out=Y
set inverter=pl_inv
set invertpin_in=A
set invertpin_out=Y
set norgate=pl_nor2
set norpin_in1=A
set norpin_in2=B
set norpin_out=Y
set nandgate=pl_nand2
set nandpin_in1=A
set nandpin_in2=B
set nandpin_out=Y
set fillcell=pl_fill
set decapcell=""
set antennacell=""
set antennapin_in=""

set tiehi=""
set tiehipin_out=""
set tielo=""
set tielopin_out=""

set separator=""
set techfile=SCN6M_SUBM.10
set magicrc=pl018.magicrc	;# written by step5_library/run.sh (absolute paths)
set gdsfile=""

# Option defaults (as osu018)
set fanout_options="-l 100 -c 20"
set via_stacks="1"
set vesta_options="--summary reports --long"
set addspacers_options="-stripe 2.0 50.0 PG"
set xspice_options="-io_time=1n -time=100p -idelay=10p -odelay=100p -cload=500f"
